   pub struct Bench {
       pub events: Vec<GameEvent>,
       pub rng: Rng,
   }

   impl Bench {
       pub fn new(state: &GameState) -> Bench {
           Bench {
               events: Vec::new(),
               rng: Rng::new(&state.seed, state.rng_cursor),
